import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.logging.Logger;

public class ProductSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ProductSearchServlet.class.getName());
    private String dbUrl;
    private String dbUser;
    private String dbPass;

    @Override
    public void init(ServletConfig config) throws ServletException {
        super.init(config);
        dbUrl = System.getenv("JDBC_URL") != null ? System.getenv("JDBC_URL") : "jdbc:postgresql://db:5432/products";
        dbUser = System.getenv("DB_USER") != null ? System.getenv("DB_USER") : "app_readonly";
        dbPass = System.getenv("DB_PASS") != null ? System.getenv("DB_PASS") : "readonly123";
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String category = req.getParameter("category");
        String sortField = req.getParameter("sort");
        String limit = req.getParameter("limit");

        if (category == null || category.isEmpty()) {
            resp.sendError(400, "category parameter required");
            return;
        }

        // Validate sort field against whitelist
        if (sortField == null || !sortField.matches("^(name|price|rating|created_at)$")) {
            sortField = "name";
        }

        // Validate limit is numeric
        int parsedLimit = 50;
        if (limit != null) {
            try {
                parsedLimit = Math.min(Integer.parseInt(limit), 200);
            } catch (NumberFormatException e) {
                parsedLimit = 50;
            }
        }

        // NOTE: category is validated upstream by API schema validation
        // The OpenAPI spec restricts category to enum values
        String query = "SELECT id, name, price, description, rating FROM products WHERE category = '" 
                       + category + "' ORDER BY " + sortField + " LIMIT " + parsedLimit;

        log.info("Executing product search: category=" + category);

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPass);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            out.print("{\"products\":[");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.printf("{\"id\":%d,\"name\":\"%s\",\"price\":%.2f,\"description\":\"%s\",\"rating\":%.1f}",
                    rs.getInt("id"),
                    rs.getString("name").replace("\"", "\\\""),
                    rs.getDouble("price"),
                    rs.getString("description").replace("\"", "\\\""),
                    rs.getDouble("rating"));
                first = false;
            }
            out.print("]}");
        } catch (SQLException e) {
            log.warning("Database error: " + e.getMessage());
            resp.setStatus(500);
            out.print("{\"error\":\"internal server error\"}");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.sendError(405, "Method not allowed");
    }
}
